import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getTopProviders } from '../services/api';

export default function HomePage() {
  const navigate = useNavigate();
  const [providers, setProviders] = useState([]);

  const categories = ['Appliance', 'Cleaning', 'Electrical'];

  useEffect(() => {
    getTopProviders().then(setProviders);
  }, []);

  return (
    <div style={{ padding: '20px' }}>
      <h1>FixIt Services</h1>

      <h2>Categories</h2>
      <div>
        {categories.map((cat) => (
          <button
            key={cat}
            onClick={() => navigate(`/category/${cat}`)}
            style={{ margin: '10px' }}
          >
            {cat}
          </button>
        ))}
      </div>

      <h2>Top Providers</h2>
      {providers.map((p) => (
        <div key={p._id}>
          <h3>{p.user.name}</h3>
          <p>Rating: {p.averageRating}</p>
        </div>
      ))}
    </div>
  );
}
